#define PI 3.14159265359

const float numParticles = 7.0;
const float glowMultiplier = 3.7;

precision highp float; 

vec4 particles1(in vec2 fragCoord, out vec2 particlePositions[100]) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float time = iTime * 0.54;
    vec3 color = vec3(0.0);
    float intensity = 0.0;

    int NUM_PARTICLES = int(numParticles);
    float dynamicScale = 3.14 + sin(iTime * 0.21) * 0.8;
    float dd = 0.;
    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = (sin(iTime) + 1.0) / 2.0 * id / 30.0;

        float theta = fract(id + particleTime * 0.09) * 20.0 * dynamicScale;
        float phi = fract(id * 1.618 + particleTime * 0.015) * 2.0 * dynamicScale;

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * -sin(theta),
            cos(phi)
        );

        float angle = time * 0.468;
        mat3 rotation = mat3(
            cos(angle), 0.0, -sin(angle),
            0.0, 1.0, 0.0,
            sin(angle), 0.0, cos(angle)
        );
        spherePos = rotation * spherePos;


        vec2 screenPos = spherePos.xy / (spherePos.z + 1.4 + (sin(time) + 1.0) / 4.0);
        particlePositions[i] = screenPos;
vec2 mouseUV = (iMouse.xy / iResolution.xy) * 2.0 - 1.0;
        mouseUV.x *= iResolution.x / iResolution.y;
        float mouseDist = length(uv - mouseUV);
        float mouseForce = 0.02 * exp(-mouseDist * 1.0);
        screenPos += normalize(uv - mouseUV) * mouseForce;


        float dist = length(uv - screenPos);
        dd += pow(abs(dist), 2.1);
        float glow = exp(-dist * glowMultiplier);
        intensity += glow * (0.9 + abs(sin(iTime / 100.0)));
        color += glow * vec3(
            0.4 + 0.6 * sin(id * PI * 2.0),
            0.3 + 0.4 * sin(time * 2.0),
            1.0
        );
    }
    dd=log(sqrt(sqrt(dd)))*1.61;
    if (intensity < 0.9) return vec4(.40 / exp(intensity));
    else if (intensity < 1.39) return vec4(color.ggg * vec3(exp(intensity * 1.10)), 1.-dd);
    else if (intensity < 1.69) return vec4(color.rgb * vec3(exp(intensity * 1.10)), 1.-dd);
    else return vec4(0.7+color.brg / .5 * intensity, 1.0-dd);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){

    vec2 particlePositions[100];
    vec4 color1 = particles1(fragCoord, particlePositions);
    //vec4 color2 = particles2(fragCoord, particlePositions);
   // float blendFactor = exp(-length(color1 - color2) * 3.0);
    vec4 finalColor = mix(color1, color1.grba, .50);
    fragColor = finalColor;
}

